import {experiment} from './forest.js';
import {evaluate} from '../core.js';
export {experiment};
export function risks(f){const spec=[['moisture',0,100],['days',0,3650],['surface',-50,80],['rain',0,5000]];const missing=spec.filter(([k,min,max])=>typeof f[k]!=='number'||!Number.isFinite(f[k])||f[k]<min||f[k]>max).map(([k])=>k);if(missing.length)return {status:'DATOS INSUFICIENTES',missing};const r=evaluate(f);return {...r,missing:[],method:'Reglas experimentales v1; no probabilidades',trace:[{rule:'H1',input:{moisture:f.moisture,days:f.days},formula:'min(100, max(0,(30−humedad)×4)+min(40,días×2))',score:r.water,contribution:r.water*.5},{rule:'T1',input:{surface:f.surface,crop:f.crop,stage:f.stage},formula:'min(100,max(0,(Tsuperficie−32)×15)); factor 1 para mango en floración, 0.5 en otro caso',score:r.heat,contribution:r.heat*.3},{rule:'F1',input:{rain7d:f.rain},formula:'min(100,lluvia7d×2)',score:r.rain,contribution:r.rain*.2}],limits:['Humedad superficial no mide raíces.','Temperatura superficial no equivale a temperatura del aire o foliar.','Lluvia es un indicador de inspección; no diagnostica antracnosis.']};}
